-- SYS0012 APIs (3)
MERGE INTO SCM_ADM_API_M t USING (SELECT 'API_SYS0012_APPROVE' API_ID FROM DUAL) s ON (t.API_ID=s.API_ID)
 WHEN MATCHED THEN UPDATE SET API_TP_CD='POST', API_MSG_ID='MSG_API_SYS0012_MAIN_APPROVE', API_URL='P_SYS0012_APPROVE', USE_YN='Y', LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
 WHEN NOT MATCHED THEN INSERT (API_ID, API_TP_CD, API_MSG_ID, API_URL, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
   VALUES ('API_SYS0012_APPROVE','POST','MSG_API_SYS0012_MAIN_APPROVE','P_SYS0012_APPROVE','Y','admin',SYSDATE,'admin',SYSDATE);
MERGE INTO SCM_ADM_API_M t USING (SELECT 'API_SYS0012_GET_APPROVAL_LIST' API_ID FROM DUAL) s ON (t.API_ID=s.API_ID)
 WHEN MATCHED THEN UPDATE SET API_TP_CD='POST', API_MSG_ID='MSG_API_SYS0012_MAIN_SEARCH', API_URL='P_SYS0012_GET_APPROVAL_LIST', USE_YN='Y', LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
 WHEN NOT MATCHED THEN INSERT (API_ID, API_TP_CD, API_MSG_ID, API_URL, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
   VALUES ('API_SYS0012_GET_APPROVAL_LIST','POST','MSG_API_SYS0012_MAIN_SEARCH','P_SYS0012_GET_APPROVAL_LIST','Y','admin',SYSDATE,'admin',SYSDATE);
MERGE INTO SCM_ADM_API_M t USING (SELECT 'API_SYS0012_REJECT' API_ID FROM DUAL) s ON (t.API_ID=s.API_ID)
 WHEN MATCHED THEN UPDATE SET API_TP_CD='POST', API_MSG_ID='MSG_API_SYS0012_MAIN_REJECT', API_URL='P_SYS0012_REJECT', USE_YN='Y', LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
 WHEN NOT MATCHED THEN INSERT (API_ID, API_TP_CD, API_MSG_ID, API_URL, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
   VALUES ('API_SYS0012_REJECT','POST','MSG_API_SYS0012_MAIN_REJECT','P_SYS0012_REJECT','Y','admin',SYSDATE,'admin',SYSDATE);
COMMIT;
